<body>
<main class="wrap">
  <h1>Hand-Drawn Budget Tracker</h1>
  <p class="sub">Enter your monthly income and your spending by category — then watch the sketchy bar chart draw itself.</p>

  <div class="card">
    <h2>Monthly income</h2>
    <div class="field">
      <label for="income">Income for the month</label>
      <input id="income" type="number" min="0" step="any" inputmode="decimal" placeholder="e.g. 3200">
    </div>
  </div>

  <div class="card">
    <h2>Spending by category</h2>
    <form id="addForm">
      <div class="add-row">
        <div class="field">
          <label for="catName">Category</label>
          <input id="catName" type="text" placeholder="e.g. Groceries" autocomplete="off">
        </div>
        <div class="field">
          <label for="catAmt">Amount</label>
          <input id="catAmt" type="number" min="0" step="any" inputmode="decimal" placeholder="0">
        </div>
      </div>
      <div style="margin-top:12px;">
        <button type="submit" class="btn btn-accent">Add spending</button>
      </div>
    </form>
    <div id="list" style="margin-top:14px;"></div>
  </div>

  <div class="stat-row" id="stats"></div>

  <div class="card">
    <h2>Where it went</h2>
    <div class="chart-wrap" id="chart"></div>
  </div>

  <p class="sr" id="status" aria-live="polite"></p>
</main>

<script>
(function(){
  var KEY = 'budget-tracker-v1';
  var income = 0;
  var categories = [];
  var canSave = !!(window.alfy && window.alfy.storage && window.alfy.storage.get);
  var statusEl = document.getElementById('status');
  var incomeInput = document.getElementById('income');
  var nameInput = document.getElementById('catName');
  var amtInput = document.getElementById('catAmt');

  function fmt(n){ return (n<0?'-':'') + '$' + Math.abs(Math.round(n)).toLocaleString('en-US'); }

  function announce(msg){ statusEl.textContent = msg; }

  function save(){
    if(!canSave) return;
    try { window.alfy.storage.set(KEY, { income: income, categories: categories }); } catch(e){}
  }

  function load(){
    if(!canSave) return;
    try {
      var d = window.alfy.storage.get(KEY);
      if(d){
        income = Number(d.income) || 0;
        categories = Array.isArray(d.categories) ? d.categories : [];
      }
    } catch(e){}
    incomeInput.value = income ? income : '';
    render();
  }

  function renderStats(){
    var spent = categories.reduce(function(s,c){ return s + (Number(c.amount)||0); }, 0);
    var left = income - spent;
    var el = document.getElementById('stats');
    el.innerHTML =
      '<div class="stat"><div class="k">Income</div><div class="v">' + fmt(income) + '</div></div>' +
      '<div class="stat"><div class="k">Spent</div><div class="v">' + fmt(spent) + '</div></div>' +
      '<div class="stat"><div class="k">Left to spend</div><div class="v ' + (left<0?'neg':'') + '">' + fmt(left) + '</div></div>';
  }

  function renderList(){
    var el = document.getElementById('list');
    if(categories.length === 0){
      el.innerHTML = '<p class="empty">No spending yet. Add your first category above — like <strong>Groceries</strong> or <strong>Rent</strong> — to see it on the chart.</p>';
      return;
    }
    var html = '<ul style="list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:8px;">';
    categories.forEach(function(c, i){
      html += '<li style="display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px;background:var(--surface-page);border:1px solid var(--border-default);border-radius:10px;">' +
        '<span><strong>' + escapeHtml(c.name) + '</strong> <span style="color:var(--text-muted);">· ' + fmt(c.amount) + '</span></span>' +
        '<button class="btn btn-ghost" data-del="' + i + '" aria-label="Remove ' + escapeHtml(c.name) + '">Remove</button>' +
        '</li>';
    });
    html += '</ul>';
    el.innerHTML = html;
    Array.prototype.forEach.call(el.querySelectorAll('[data-del]'), function(b){
      b.addEventListener('click', function(){
        var idx = Number(b.getAttribute('data-del'));
        var removed = categories.splice(idx,1)[0];
        save(); render();
        announce('Removed ' + removed.name + '.');
      });
    });
  }

  function escapeHtml(s){
    return String(s).replace(/[&<>"]/g, function(ch){
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[ch];
    });
  }

  function renderChart(){
    var el = document.getElementById('chart');
    if(categories.length === 0){
      el.innerHTML = '<p class="empty">Your hand-drawn chart will appear here once you add spending.</p>';
      return;
    }
    var data = categories.slice().sort(function(a,b){ return b.amount - a.amount; });
    var maxVal = Math.max.apply(null, data.map(function(d){ return d.amount; }));
    if(maxVal <= 0) maxVal = 1;

    var rowH = 62;
    var W = Math.max(el.clientWidth || 0, 300);
    var labelW = Math.min(150, Math.max(90, W * 0.26));
    var barArea = W - labelW - 8;
    var H = data.length * rowH + 12;
    var seed = 12345;
    function rnd(){ seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }

    var svg = '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" role="img" aria-label="Bar chart of spending by category">';

    data.forEach(function(d, i){
      var y = i * rowH + 6;
      var barH = rowH - 26;
      var w = Math.max(2, (d.amount / maxVal) * barArea);
      var x0 = labelW;
      var x1 = x0 + w;
      var top = y, bot = y + barH;
      var jit = function(){ return (rnd()-0.5)*2.2; };

      // sketchy bar fill (accent)
      var fillPts = [
        [x0+jit(), top+jit()], [x1+jit(), top+jit()],
        [x1+jit(), bot+jit()], [x0+jit(), bot+jit()]
      ];
      var fillPath = 'M ' + fillPts[0][0].toFixed(1) + ' ' + fillPts[0][1].toFixed(1);
      for(var p=1;p<fillPts.length;p++){ fillPath += ' L ' + fillPts[p][0].toFixed(1) + ' ' + fillPts[p][1].toFixed(1); }
      fillPath += ' Z';
      svg += '<path d="' + fillPath + '" fill="var(--accent)" opacity="0.28"></path>';

      // sketchy outline (double stroke)
      var outline = 'M ' + (x0+jit()).toFixed(1) + ' ' + (top+jit()).toFixed(1) +
        ' L ' + (x1+jit()).toFixed(1) + ' ' + (top+jit()).toFixed(1) +
        ' L ' + (x1+jit()).toFixed(1) + ' ' + (bot+jit()).toFixed(1) +
        ' L ' + (x0+jit()).toFixed(1) + ' ' + (bot+jit()).toFixed(1) + ' Z';
      svg += '<path d="' + outline + '" fill="none" stroke="var(--text-primary)" stroke-width="1.4" opacity="0.7"></path>';
      svg += '<path d="' + outline + '" fill="none" stroke="var(--text-primary)" stroke-width="1.1" opacity="0.35" transform="translate(' + (rnd()*1.6).toFixed(1) + ' ' + (rnd()*1.6).toFixed(1) + ')"></path>';

      // label
      var label = d.name.length > 14 ? d.name.slice(0,13) + '…' : d.name;
      svg += '<text x="' + (labelW-10) + '" y="' + (top + barH/2 + 4) + '" text-anchor="end" font-family="Helvetica, Arial, sans-serif" font-size="13" fill="var(--text-primary)">' + escapeHtml(label) + '</text>';

      // amount
      var amtTxt = fmt(d.amount);
      var inside = w > amtTxt.length * 8 + 16;
      if(inside){
        svg += '<text x="' + (x1-8) + '" y="' + (top + barH/2 + 4) + '" text-anchor="end" font-family="Helvetica, Arial, sans-serif" font-size="12" fill="var(--text-primary)">' + amtTxt + '</text>';
      } else {
        svg += '<text x="' + (x1+8) + '" y="' + (top + barH/2 + 4) + '" text-anchor="start" font-family="Helvetica, Arial, sans-serif" font-size="12" fill="var(--text-muted)">' + amtTxt + '</text>';
      }
    });

    svg += '</svg>';
    el.innerHTML = svg;
  }

  function render(){
    renderStats();
    renderList();
    renderChart();
  }

  // income handler
  incomeInput.addEventListener('input', function(){
    income = Number(incomeInput.value) || 0;
    save(); renderStats(); renderChart();
  });

  // add handler
  document.getElementById('addForm').addEventListener('submit', function(e){
    e.preventDefault();
    var name = nameInput.value.trim();
    var amt = Number(amtInput.value);
    if(!name){ announce('Please enter a category name.'); nameInput.focus(); return; }
    if(!(amt > 0)){ announce('Please enter an amount greater than zero.'); amtInput.focus(); return; }
    categories.push({ name: name, amount: amt });
    save(); render();
    nameInput.value = ''; amtInput.value = ''; nameInput.focus();
    announce('Added ' + name + ' at ' + fmt(amt) + '.');
  });

  window.addEventListener('resize', function(){ renderChart(); });

  load();
})();
</script>
</body>
